"""Checked pose Jacobian safety on fully generated byte-array photographs.

No independent face evidence is included or claimed.
Author: John Khan.
"""

from __future__ import annotations

import math

import numpy as np
import pytest

from plumb_api.commands.errors import CommandUnavailable, CommandValidationError
from plumb_api.commands.frames import ImageFrame
from plumb_api.commands.levels import DecimalLevel
from plumb_api.commands.pose import PoseOnlyProcessor
from plumb_api.commands.pose_geometry import PoseEvidence, PoseHandle
from plumb_api.commands.pose_safety import (
    PoseSafetyRules,
    choose_pose_dose,
    inverse_jacobians,
)


def picture(width: int = 79, height: int = 91, channels: int = 4) -> ImageFrame:
    yy, xx = np.indices((height, width))
    red = np.asarray((xx * 5 + yy * 9 + 33) % 255, dtype=np.uint8)
    green = np.asarray((xx * 7 + yy * 3 + 21) % 255, dtype=np.uint8)
    blue = np.asarray((xx * 11 + yy * 2 + 51) % 255, dtype=np.uint8)
    colour = np.stack((red, green, blue), axis=2)
    if channels == 4:
        alpha = np.asarray((xx + yy * 4 + 5) % 256, dtype=np.uint8)
        colour = np.dstack((colour, alpha))
    return ImageFrame(width, height, channels, colour.tobytes())


def controls(frame: ImageFrame) -> PoseEvidence:
    mask = np.zeros((frame.height, frame.width), dtype=np.uint8)
    mask[frame.height // 4:-4, 9:-9] = 255
    handles = (
        PoseHandle("left", 0.25, 0.4, -0.032, 0.002),
        PoseHandle("right", 0.75, 0.4, 0.032, 0.002),
        PoseHandle("waist", 0.52, 0.72, 0.0, -0.022),
    )
    return PoseEvidence(frame.width, frame.height, mask.tobytes(), handles, "synthetic_test")


def test_identity_mapping_has_unit_jacobian() -> None:
    yy, xx = np.mgrid[0:7, 0:9]
    x = np.asarray(xx, dtype=np.float64)
    y = np.asarray(yy, dtype=np.float64)
    sample = inverse_jacobians(x, y, 1.0, 1.0)
    assert sample.shape == (6, 8)
    assert np.all(sample == 1.0)


def test_inverted_sampling_grid_is_negative() -> None:
    yy, xx = np.mgrid[0:7, 0:9]
    x = np.asarray(8 - xx, dtype=np.float64)
    y = np.asarray(yy, dtype=np.float64)
    sample = inverse_jacobians(x, y, 1.0, 1.0)
    assert np.all(sample == -1.0)


def test_skewed_sampling_grid_has_correct_determinant() -> None:
    yy, xx = np.mgrid[0:5, 0:6]
    x = np.asarray(0.6 * xx + 0.25 * yy, dtype=np.float64)
    y = np.asarray(0.2 * xx + 1.2 * yy, dtype=np.float64)
    assert np.allclose(inverse_jacobians(x, y, 1.0, 1.0), 0.67)


@pytest.mark.parametrize("changed", [0, 1, 2, 3, 4])
def test_grid_shape_refusal(changed: int) -> None:
    source = np.ones((3, 4), dtype=np.float64)
    x = source.copy()
    y = source.copy()
    dx = 1.0
    dy = 1.0
    if changed == 0:
        x[0, 0] = math.nan
    elif changed == 1:
        y[0, 2] = math.inf
    elif changed == 2:
        x = np.ones((4,), dtype=np.float64)
    elif changed == 3:
        dx = 0.0
    else:
        y = np.ones((2, 4), dtype=np.float64)
    with pytest.raises(CommandValidationError):
        inverse_jacobians(x, y, dx, dy)


@pytest.mark.parametrize("bad", [0.0, -0.01, 1.1, math.inf, math.nan])
def test_invalid_threshold_rules_fail(bad: float) -> None:
    with pytest.raises(CommandValidationError):
        PoseSafetyRules(minimum_determinant=bad)


@pytest.mark.parametrize("bad", [-1.0, 1.01, math.nan, math.inf])
def test_invalid_strength_is_rejected(bad: float) -> None:
    with pytest.raises(CommandValidationError):
        choose_pose_dose(controls(picture()), bad)


def test_noop_is_measurably_neutral() -> None:
    decision = choose_pose_dose(controls(picture()), 0.0)
    assert decision.used_dose == 0
    assert decision.retention == 1
    assert decision.smallest_determinant == 1
    assert decision.public_metadata()["realface_verified"] is False


@pytest.mark.parametrize("level", [0.025, 0.1, 0.25, 0.5, 0.75, 1.0])
def test_normal_controls_stay_safe(level: float) -> None:
    result = choose_pose_dose(controls(picture()), level)
    assert 0 < result.used_dose <= level
    assert result.checked_cells == 48 * 48
    assert result.smallest_determinant >= 0.25
    assert result.largest_determinant <= 3.0
    assert result.backoff_count >= 0
    assert result.retention >= 0.25


def test_guard_reacts_to_impossibly_high_strict_floor() -> None:
    source = controls(picture())
    strict = PoseSafetyRules(minimum_determinant=0.999, minimum_retained_dose=0.95)
    with pytest.raises(CommandUnavailable) as failure:
        choose_pose_dose(source, 1.0, strict)
    assert failure.value.code == "pose_fold_risk"


def test_report_excludes_person_geometry_and_paths() -> None:
    source = controls(picture())
    report = choose_pose_dose(source, 0.8).public_metadata()
    text = str(report)
    assert "left" not in text
    assert "right" not in text
    assert "body_mask" not in text
    assert "handles" not in text
    assert report["checked_cells"] == 2304


def test_render_guard_is_exact_on_preview_export_and_tiled() -> None:
    frame = picture()
    outputs = []
    results = []
    for tile in (16, 32, 64, 96):
        engine = PoseOnlyProcessor(tile_size=tile)
        engine.open_photo(frame, controls(frame))
        outputs.append(engine.render(frame, level=DecimalLevel(45), preview=True))
        results.append(engine.render(frame, level=DecimalLevel(45), preview=False))
        assert engine.last_report is not None
        assert engine.last_report.fold_minimum is not None
        assert engine.last_report.fold_retention >= 0.25
    assert len({output.pixels for output in outputs + results}) == 1


def test_photo_replacement_invalidates_cached_safety() -> None:
    frame = picture()
    engine = PoseOnlyProcessor()
    evidence = controls(frame)
    engine.open_photo(frame, evidence)
    engine.render(frame, level=DecimalLevel(50), preview=True)
    assert engine.last_report is not None
    engine.close_photo()
    with pytest.raises(CommandUnavailable):
        engine.render(frame, level=DecimalLevel(50), preview=True)
    engine.open_photo(frame, evidence)
    result = engine.render(frame, level=DecimalLevel(50), preview=True)
    assert result.pixels != frame.pixels


def test_alpha_is_preserved_after_guarded_resampling() -> None:
    frame = picture(channels=4)
    engine = PoseOnlyProcessor()
    engine.open_photo(frame, controls(frame))
    edited = engine.render(frame, level=DecimalLevel(50), preview=False)
    assert frame.pixels[3::4] == edited.pixels[3::4]
    assert engine.last_report is not None
    assert engine.last_report.alpha_unchanged
